from Crypto.Cipher import AES
import base64


def aes_ecb_decrypt_return_hex(cipher_b64: str, key_str: str) -> str:
    # Base64 解码
    cipher_bytes = base64.b64decode(cipher_b64)

    # UTF8 编码的 key，CryptoJS.enc.Utf8.parse 也只是 UTF8 编码，不截断
    key_bytes = key_str.encode('utf-8')
    if len(key_bytes) not in (16, 24, 32):
        key_bytes = key_bytes.ljust(16, b'\0')  # 如果太短，CryptoJS 不报错而是 padding

    # ECB 解密 + PKCS7 padding（CryptoJS 默认就是这个）
    cipher = AES.new(key_bytes, AES.MODE_ECB)
    decrypted_bytes = cipher.decrypt(cipher_bytes)

    # PKCS7 去填充
    pad_len = decrypted_bytes[-1]
    if not 1 <= pad_len <= 16:
        raise ValueError("PKCS7 padding length invalid: {}".format(pad_len))
    plaintext_bytes = decrypted_bytes[:-pad_len]

    # 重点：转 HEX 字符串（等价 JS 中 .toString(CryptoJS.enc.Hex)）
    return plaintext_bytes.hex()


# 示例调用
cipher_b64 = ""

key = "a08bfa0f559a4e12"

hex_plaintext = aes_ecb_decrypt_return_hex(cipher_b64, key)
print("解密后（Hex）：", hex_plaintext)
